var h1 = msg.payload.nodo1;
var h2 = msg.payload.nodo2;
var h3 = msg.payload.nodo3;

var v1 = msg.payload.valvula1;
var v2 = msg.payload.valvula2;
var v3 = msg.payload.valvula3;

var bomba = msg.payload.bomba;
var temperatura = msg.payload.temp;
var ha = msg.payload.humAmb;
var can1 = msg.payload.can1;
var can2 = msg.payload.can2;
var can3 = msg.payload.can3;

return [
 {payload:h1},   
 {payload:h2},   
 {payload:h3},   
 {payload:v1},   
 {payload:v2},   
 {payload:v3},   
 {payload:bomba}, 
 {payload:temperatura}, 
 {payload:ha},    
 {payload:can1},
 {payload:can2},
 {payload:can3} 
];

if (msg.payload === "manual") {

    return [
        {enabled: true},   // habilitar switch bomba
        {enabled: true},   // habilitar switch valvula
        {enabled: true},  
        {enabled: true}     
    ];

}

if (msg.payload === "auto") {

    return [
        {enabled: false},  // bloquear switch bomba
        {enabled: false},  // bloquear switch valvula
        {enabled: false},
        {enabled: false}  
    ];

}

return null;

// === Reemplazar el contenido de la función "datos" en Node-RED ===
//
// Antes: guardaba fecha/hora_local/zona1-3/bomba/riego en la colección
// "sensores", mezclando telemetría con estado de control.
//
// Ahora: separa la telemetría física (lo que consumirá la LSTM) de los
// eventos de control (modo, riego on/off), y usa nombres de campo
// consistentes con el esquema de la colección "telemetria".
//
// IMPORTANTE: además de pegar este código, hay que cambiar en el nodo
// "mongodb out" de este flujo la colección de "sensores" a "telemetria".

let d = msg.payload; // JSON ya parseado desde el ESP32 (nodo1, nodo2, ... can3)

msg.payload = {
    timestamp: new Date(),
    zona1_humedad: d.nodo1,
    zona2_humedad: d.nodo2,
    zona3_humedad: d.nodo3,
    temp_ambiente: d.temp,
    hum_ambiente: d.humAmb,
    valvula1: d.valvula1,
    valvula2: d.valvula2,
    valvula3: d.valvula3,
    bomba: d.bomba,
    can1_online: d.can1,
    can2_online: d.can2,
    can3_online: d.can3
};

return msg;

let datos = msg.payload;

let zona1 = [];
let zona2 = [];
let zona3 = [];

for (let i = 0; i < datos.length; i++) {

    zona1.push({
        x: new Date(datos[i].timestamp),
        y: datos[i].zona1_humedad
    });

    zona2.push({
        x: new Date(datos[i].timestamp),
        y: datos[i].zona2_humedad
    });

    zona3.push({
        x: new Date(datos[i].timestamp),
        y: datos[i].zona3_humedad
    });
}

msg.payload = [
    {
        series: ["Z1","Z2","Z3"],
        data: [zona1, zona2, zona3],
        labels: []
    }
];

return msg;

let fecha = new Date(msg.payload);

let inicio = new Date(fecha);
inicio.setHours(0, 0, 0, 0);

let fin = new Date(fecha);
fin.setHours(23, 59, 59, 999);

msg.payload = [
    { "timestamp": { "$gte": inicio, "$lte": fin } },
    { sort: { timestamp: 1 }, limit: 1000 }
];

return msg;

let datos = msg.payload;

let inicioRiego = null;
let tiempoTotal = 0;

for (let i = 0; i < datos.length; i++) {

    let tipo = datos[i].tipo;   // "riego_on" o "riego_off" (colección eventos)
    let tiempo = new Date(datos[i].timestamp);

    // inicio del riego
    if (tipo === "riego_on" && inicioRiego === null) {
        inicioRiego = tiempo;
    }

    // fin del riego
    if (tipo === "riego_off" && inicioRiego !== null) {

        let fin = tiempo.getTime();
        tiempoTotal += (fin - inicioRiego.getTime());

        inicioRiego = null;
    }
}

let minutos = tiempoTotal / 60000;

msg.payload = minutos.toFixed(2) + " minutos";

return msg;

// Guardar valores
if (msg.topic === "on") {
    flow.set("on", Number(msg.payload));
    return null;
}

if (msg.topic === "off") {
    flow.set("off", Number(msg.payload));
    return null;
}

if (msg.topic === "nodo") {
    flow.set("nodo", msg.payload);
    return null;
}

// Enviar
if (msg.topic === "enviar" || msg.payload === 1) {

    let nodo = flow.get("nodo") || 1;
    let on   = flow.get("on") || 30;
    let off  = flow.get("off") || 50;

    // Validaciones
    if (isNaN(on) || isNaN(off)) {
        node.warn("Valores inválidos");
        return null;
    }

    if (on >= off) {
        node.warn("ON debe ser menor que OFF");
        return null;
    }

    msg.payload = {
        nodo: nodo,
        on: on,
        off: off
    };

    return msg;
}

return null;

let bombaActual = msg.payload.bomba;
let bombaAnterior = flow.get("bomba_anterior");

if (bombaAnterior === undefined) {
    flow.set("bomba_anterior", bombaActual);
    return null; // primera lectura, no hay transición que registrar
}

if (bombaActual !== bombaAnterior) {
    flow.set("bomba_anterior", bombaActual);
    msg.payload = {
        timestamp: new Date(),
        tipo: bombaActual === 1 ? "riego_on" : "riego_off"
    };
    return msg;
}

return null; // sin cambio, no se emite evento

let desde = new Date(Date.now() - 24 * 60 * 60 * 1000); // últimas 24h, mismo criterio que HISTORIAL_HORAS

msg.payload = [
    { timestamp: { $gte: desde } },
    { sort: { timestamp: 1 }, limit: 5000 }
];

return msg;
